# derive quadrant layouts by carrying demo7's value-position mapping, greedily match source occurrences
D=[[0,0,0,9,0],[0,0,0,7,9],[0,3,9,0,0],[6,0,0,0,0],[0,4,3,4,0]]
TR=[[0,6,0,0,0],[4,0,3,0,0],[3,0,9,0,0],[4,0,0,7,9],[0,0,0,9,0]]
BL=[[0,9,0,0,0],[9,7,0,0,4],[0,0,9,0,3],[0,0,3,0,4],[0,0,0,6,0]]
BR=[[4,3,4,0,0],[0,0,0,0,6],[0,9,3,0,0],[9,7,0,0,0],[0,0,6,0,0]]
from collections import defaultdict
def perm(src,dst):
 pools=defaultdict(list)
 for i,v in enumerate(sum(src,[])): pools[v].append(i)
 m=[]
 for v in sum(dst,[]): m.append(pools[v].pop(0))
 return m
for q in (TR,BL,BR): print(perm(D,q))
